class ConfigDevice(FakeDevice):
    def __init__(self, pin=""):
        super().__init__()
        self.pin = pin
        self.http_unlocked = not pin
        self.cfg = {"um": {"BleApiBridge": {"enabled": True, "device-name": "original",
                    "max-request-bytes": 4096, "pairing-code": 874619}},
                    "nw": {"linked_remote": ["102030405060"]}, "id": {"name": "Fixture"},
                    "ota": {"lock": False, "lock-wifi": True, "same-subnet": True, "aota": False, "pskl": 8}}
        self.cfg_posts = []
        self.security_posts = []
        self.ble_pin_attempts = []
        self.clients = []
        self.fail_after_apply = False
        self.fail_pin_after_apply = False
        self.cancel_pin_after_apply = False

    def apply(self, update):
        self.cfg_posts.append(copy.deepcopy(update))
        top = self.cfg["um"]["BleApiBridge"]
        before = copy.deepcopy(top)
        top.update(update.get("um", {}).get("BleApiBridge", {}))
        top["device-name"] = top["device-name"].encode()[:29].decode(errors="ignore")
        self.cfg["nw"]["linked_remote"] = copy.deepcopy(update.get("nw", {}).get("linked_remote", []))
        self.info["ble"]["maxRequest"] = top["max-request-bytes"]
        self.state["BleApiBridge"] = {"enabled": top["enabled"]}
        if top != before:
            for client in self.clients:
                client.is_connected = False


class ConfigClient(FakeClient):
    def __init__(self, device, **kwargs):
        super().__init__(device, **kwargs)
        device.clients.append(self)

    async def connect(self):
        if not self.device.cfg["um"]["BleApiBridge"]["enabled"]:
            raise ConnectionError("Disabled")
        await super().connect()

    async def request(self, method, path, body=""):
        if not self.is_connected:
            raise ConnectionError("Disconnected")
        if path != "/json/cfg":
            return await super().request(method, path, body)
        if method == "GET":
            status, value = (401, {}) if self.device.pin else (200, self.device.cfg)
        else:
            update = json.loads(body)
            self.device.ble_pin_attempts.append(update.get("pin"))
            if self.device.pin and update.get("pin") != self.device.pin:
                status, value = 401, {"success": False}
            else:
                self.device.apply(update)
                if self.device.fail_after_apply:
                    self.device.fail_after_apply = False
                    raise ConnectionError("Write applied but reply lost; SECRET")
                status, value = 200, {"success": True}
        return bridge.BridgeResponse(status, "application/json", json.dumps(value))

    async def stop_notify(self, characteristic):
        pass

    async def start_notify(self, characteristic, callback):
        pass

    async def write_gatt_char(self, characteristic, payload, response):
        if int.from_bytes(payload[:2], "little") > self.device.info["ble"]["maxRequest"]:
            self.is_connected = False


class ConfigOracle(FakeOracle):
    async def request(self, method, path, body=None):
        if path == "/json/state":
            self.device.http_unlocked = not self.device.pin or body.get("pin") == self.device.pin
            return 200, self.device.snapshot()
        if method == "GET":
            # Core HTTP GET /json/cfg is public even when settings are locked.
            return 200, copy.deepcopy(self.device.cfg)
        if "pin" in body:
            self.device.http_unlocked = not self.device.pin or body["pin"] == self.device.pin
        if not self.device.http_unlocked and self.device.pin:
            return 401, {}
        self.device.apply(body)
        return 200, {"success": True}

    async def settings(self, method, path, fields=None):
        if path == "/settings/lock":
            self.device.http_unlocked = not self.device.pin
            return 200, "lock state updated"
        if not self.device.http_unlocked:
            return 401, "PIN required"
        mapping = {"NO": "lock", "OW": "lock-wifi", "AO": "aota", "SU": "same-subnet"}
        ota = self.device.cfg["ota"]
        if method == "GET":
            script = 'd.Sf.PIN.value="' + ("0000" if self.device.pin else "") + '";'
            script += "".join(f"d.Sf.{key}.checked={int(bool(ota.get(value)))};" for key, value in mapping.items())
            return 200, script
        self.device.security_posts.append(copy.deepcopy(fields))
        if not ota["lock"]:
            for field, name in mapping.items():
                if name in ota:
                    ota[name] = field in fields
        self.device.pin = fields["PIN"]
        if self.device.fail_pin_after_apply:
            self.device.fail_pin_after_apply = False
            raise ConnectionError("PIN applied but response lost; SECRET")
        if self.device.cancel_pin_after_apply:
            self.device.cancel_pin_after_apply = False
            raise asyncio.CancelledError()
        return 200, "Security settings saved"


class ConfigTests(unittest.IsolatedAsyncioTestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.args = config.parse_args(["--address", "test", "--http-url", "http://127.0.0.1",
                                      "--output", self.temp.name, "--allow-config-tests"])
        self.device = ConfigDevice()
        self.cooldown = patch.object(config, "PIN_SETTLE_SECONDS", 0)
        self.cooldown.start()
        self.addCleanup(self.cooldown.stop)

    def runner(self, oracle=None):
        async def scanner(**kwargs):
            return {"test": (SimpleNamespace(address="test"),
                              SimpleNamespace(local_name=self.device.cfg["um"]["BleApiBridge"]["device-name"]))}

        result = config.ConfigHilRunner(self.args,
                client_factory=lambda _address, **kwargs: ConfigClient(self.device, **kwargs),
                oracle=oracle or ConfigOracle(self.device), scanner=scanner)
        # Real restart observation waits up to ten seconds when restoration is a no-op.
        async def disconnected(client):
            config.check(not client.client.is_connected, "Runtime configuration did not disconnect the old BLE link")
        result.wait_disconnected = disconnected
        return result

    def assert_safe_payloads(self):
        for value in self.device.cfg_posts:
            self.assertIs(value["sv"], False)
            self.assertEqual(value["nw"], {"linked_remote": ["102030405060"]})
            self.assertLessEqual(set(value["um"]["BleApiBridge"]), set(config.ConfigHilRunner.fields))
            self.assertNotIn("pairing-code", value["um"]["BleApiBridge"])
            self.assertLessEqual(set(value), {"sv", "um", "nw", "pin"})

    async def test_full_run_restores_exact_touched_fields_and_marks_missing_pin_coverage(self):
        initial = copy.deepcopy(self.device.cfg)
        runner = self.runner()
        self.assertEqual(await runner.run(), 2)
        self.assertEqual(self.device.cfg, initial)
        self.assert_safe_payloads()
        statuses = {record["name"]: record["status"] for record in runner.records}
        self.assertEqual(statuses["runtime_names_utf8"], "pass")
        self.assertEqual(statuses["runtime_request_limits"], "pass")
        self.assertEqual(statuses["runtime_disable_enable"], "pass")
        self.assertEqual(statuses["independent_settings_pin"], "skip")
        self.assertEqual(statuses["restore_configuration"], "pass")

    async def test_backup_is_private_ignored_and_secrets_absent_from_reports(self):
        runner = self.runner()
        await runner.setup_config()
        runner.write_reports()
        backup = Path(self.temp.name) / "private-config" / "configuration.json"
        self.assertEqual(stat.S_IMODE(backup.stat().st_mode), 0o600)
        self.assertEqual(stat.S_IMODE(backup.parent.stat().st_mode), 0o700)
        self.assertEqual((backup.parent / ".gitignore").read_text(), "*\n")
        self.assertEqual(json.loads(backup.read_text()), self.device.cfg)
        for path in Path(self.temp.name).iterdir():
            if path.is_file():
                self.assertNotIn("874619", path.read_text())

