    async def test_repeated_cancellation_during_cleanup_does_not_interrupt_pin_removal(self):
        self.args.provision_test_pin = True
        runner = self.runner()
        entered_cleanup = asyncio.Event()
        allow_cleanup = asyncio.Event()
        original = runner.restore_test_pin
        async def blocked_restore():
            entered_cleanup.set()
            await allow_cleanup.wait()
            return await original()
        runner.restore_test_pin = blocked_restore
        task = asyncio.create_task(runner.run())
        await entered_cleanup.wait()
        task.cancel()
        await asyncio.sleep(0)
        task.cancel()
        allow_cleanup.set()
        with self.assertRaises(asyncio.CancelledError):
            await task
        self.assertEqual(self.device.pin, "")
        self.assertTrue(runner.pin_restored)

