    def test_http_body_trickle_cannot_reset_body_budget(self):
        oracle = config.ConfigHttp("http://127.0.0.1", 1)
        class Trickle:
            code = 200
            calls = 0
            def __enter__(self):
                return self
            def __exit__(self, *_args):
                pass
            def read1(self, size):
                self.calls += 1
                return b"x"
        response = Trickle()
        opener = SimpleNamespace(open=lambda *_args, **_kwargs: response)
        with patch.object(config.urllib.request, "build_opener", return_value=opener), \
             patch.object(config.time, "monotonic", side_effect=[1, 1.1, 1.5, 2.1]):
            with self.assertRaisesRegex(TimeoutError, "body read deadline"):
                oracle._exchange("GET", "/json/cfg", None, "application/json")
        self.assertEqual(response.calls, 2)

