    async def test_cancelled_http_write_finishes_before_caller_cleanup(self):
        oracle = config.ConfigHttp("http://127.0.0.1", 0.1)
        entered = threading.Event()
        release = threading.Event()
        finished = threading.Event()
        def operation():
            entered.set()
            release.wait(1)
            finished.set()
            return "done"
        task = asyncio.create_task(oracle._finish_http(operation))
        while not entered.is_set():
            await asyncio.sleep(0)
        task.cancel()
        await asyncio.sleep(0)
        self.assertFalse(task.done())
        release.set()
        with self.assertRaises(asyncio.CancelledError):
            await task
        self.assertTrue(finished.is_set())


